list_categories.code:
use WebCommander\Sdk\Resources\Categories\Categories;

$response = Categories::listCategories($client, ['limit' => 10, 'offset' => 10, 'sort' => 'name', 'dir' => 'asc']);

foreach ($response->map['categories'] as $category) {
    echo $category['id'], ' ', $category['general']['name'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' categories in total', PHP_EOL;

create_category.code:
use WebCommander\Sdk\Resources\Categories\Categories;

$response = Categories::createCategory($client, ['category' => [
    'general' => ['name' => 'Seasonal Produce', 'title' => 'Seasonal Produce', 'heading' => 'Fresh this season',
        'summary' => 'Fruit and vegetables picked this week', 'parent_category' => ['id' => 4310]],
    'description' => ['content' => '<p>What is in season right now.</p>'],
    'availability_visibility' => ['visible' => true, 'custom_sorting' => true, 'default_sorting' => 'alpha_asc'],
    'tax_shipping' => ['tax_message' => 'Prices include GST'],
    'assign_products' => ['products' => [101, 102]],
]]);

echo $response->map['category']['id'], ' ', $response->map['category']['general']['url'], PHP_EOL;

update_category.code:
use WebCommander\Sdk\Resources\Categories\Categories;

$response = Categories::updateCategory($client, 4321, [
    'category' => ['general' => ['name' => 'Seasonal Produce', 'heading' => 'New heading']],
]);

echo $response->map['category']['general']['heading'], PHP_EOL;

patch_category.code:
use WebCommander\Sdk\Resources\Categories\Categories;

$response = Categories::patchCategory($client, 4321, [
    'category' => [
        'general' => ['summary' => 'Updated summary'],
        'availability_visibility' => ['visible' => false],
    ],
]);

$category = $response->map['category'];
echo $category['general']['summary'], ', visible: ', $category['availability_visibility']['visible'] ? 'true' : 'false', PHP_EOL;

patch_category_section.code:
use WebCommander\Sdk\Resources\Categories\Categories;

$response = Categories::patchCategorySection($client, 4321, 'assign_products', [
    'category' => ['assign_products' => ['products' => [101, 102, 103]]],
]);

foreach ($response->map['category']['assign_products']['products'] as $product) {
    echo $product['id'], ' ', $product['sku'], ' ', $product['name'], PHP_EOL;
}
